-- Our Little Ritual — the 90 Play With Me activities, as approved by Vee on 15 Nov 2026.
-- (code, title, category, description, instructions, prompts, minutes, energy, type, moods, materials)
insert into public.play_activities (code, title, category, description, instructions, prompts, minutes, energy, activity_type, moods, materials) values
-- Guess & Discover
(1, 'Twenty Questions: Us Edition', 'guess_discover', 'Guess a shared memory, place or object in 20 yes/no questions.', 'One of you secretly picks something from your life together. The other asks up to 20 yes/no questions to guess it. Swap.', array['A café', 'A gift', 'An inside joke', 'A song', 'A city'], 10, 'medium', 'guessing', array['playful','romantic'], null),
(2, 'Draw & Guess Speedround', 'guess_discover', 'One draws, the other guesses — against the clock.', 'Take turns: the drawer picks a word, draws it on paper and holds it to the camera. 60 seconds to guess. No letters or numbers!', array['suitcase', 'jealousy', 'sunrise', 'durian', 'empanada', 'lighthouse', 'hiccup', 'homesick'], 10, 'high', 'guessing', array['playful','silly'], 'Paper and pen'),
(3, 'What''s in My Room?', 'guess_discover', 'Describe an object near you without naming it.', 'Pick something in your room. Describe it in three clues, from vague to obvious. Your partner guesses after each clue. Swap.', array['Clue order: what it does → what it looks like → where it lives'], 10, 'medium', 'guessing', array['playful','relaxed'], null),
(4, 'Hum That Song', 'guess_discover', 'Hum a song; your partner names it.', 'Hum (no words!) a song you both might know. Partner guesses the title. Bonus point if it''s "your" song.', '{}', 5, 'high', 'guessing', array['silly','playful'], null),
(5, 'Mystery Close-Up', 'guess_discover', 'Hold an object very close to the camera and make them guess.', 'Grab something nearby and move it so close to the camera it''s unrecognisable. Slowly pull it back until your partner guesses.', '{}', 5, 'medium', 'guessing', array['playful','silly'], 'Household objects'),
(6, 'Emoji Charades', 'guess_discover', 'Describe a movie, song or memory using only emojis.', 'Send emojis in your chat app that describe a film, song or shared memory. Your partner guesses. Three rounds each.', array['Start easy: 🦁👑 → The Lion King'], 10, 'low', 'guessing', array['playful','relaxed'], 'Your chat app'),
(7, 'How Well Do You Know Me?', 'guess_discover', 'Quiz each other on your own little details.', 'Ask your partner five questions about yourself. They answer out loud. Swap. No scores — just laugh at the misses.', array['My comfort food?', 'My first job?', 'What I''m secretly scared of?', 'My go-to karaoke song?'], 15, 'medium', 'guessing', array['playful','romantic'], null),
(8, 'Guess the Snack', 'guess_discover', 'Taste something off-camera and describe it.', 'Eat a snack out of view. Describe the taste, texture and sound. Your partner guesses what it is.', '{}', 5, 'medium', 'guessing', array['silly','playful'], 'Any snack'),
(9, 'Sound Detective', 'guess_discover', 'Make a sound off-camera; your partner identifies it.', 'Hide the camera and make a sound with something around you. Partner gets three guesses. Swap.', array['Keys', 'A zip', 'A kettle', 'Pouring rice', 'A squeaky door'], 5, 'high', 'guessing', array['silly'], 'Household objects'),
(10, 'Map Mystery', 'guess_discover', 'Think of a place in the world; guide them with hotter/colder.', 'Pick a place on Earth. Your partner names places and you say "warmer" or "colder" until they find it.', array['Try somewhere you''d love to go together'], 10, 'low', 'guessing', array['playful','relaxed'], null),
(11, 'Finish My Sentence', 'guess_discover', 'Start a sentence about the two of you; your partner guesses how it ends.', 'Say the start of a sentence you''ve already finished in your head. Partner guesses the ending. Reveal yours.', array['The first time I knew…', 'You always make me laugh when…', 'Our next trip should…'], 10, 'low', 'guessing', array['romantic','playful'], null),
(12, 'Two Truths and a Lie: Childhood', 'guess_discover', 'Three stories from when you were little — one is made up.', 'Tell two true childhood stories and one believable fake. Partner guesses the lie. Swap.', '{}', 10, 'low', 'guessing', array['playful'], null),
(13, 'Guess the Year', 'guess_discover', 'Describe a year from your life; your partner guesses which.', 'Give clues about one year of your life — where you lived, what you loved, what you worried about. Partner guesses the year.', '{}', 10, 'low', 'guessing', array['deep','relaxed'], null),
(14, 'The Price Is Right: Home Edition', 'guess_discover', 'Show something from home; your partner guesses what it cost.', 'Hold up an everyday item and say what it cost in your currency. Partner guesses the price in theirs. Closest wins a compliment.', array['Great for ringgit vs pesos'], 10, 'medium', 'guessing', array['playful'], 'Everyday items'),
(15, 'Translate This', 'guess_discover', 'Teach a word from your language; your partner guesses its meaning.', 'Say a word in your language (Malay, Iban, Spanish…) and give three possible meanings. Partner picks the right one, then tries to say it.', array['Pick words that are fun to say or have no direct translation'], 10, 'low', 'guessing', array['playful','romantic'], null),
-- Creative Chaos
(16, 'Blind Portrait', 'creative_chaos', 'Draw each other without looking at the paper.', 'Look only at your partner on screen. Draw their face for 60 seconds without looking down. Reveal together.', '{}', 5, 'medium', 'drawing', array['silly','playful'], 'Paper and pen'),
(17, 'One-Line Story', 'creative_chaos', 'Build a story one sentence at a time.', 'Take turns adding one sentence to a story. Try to end it after 20 sentences — happily or chaotically.', array['Opening line: "The suitcase was not supposed to talk."'], 10, 'medium', 'storytelling', array['creative','playful'], null),
(18, 'Draw the Same Thing', 'creative_chaos', 'Both draw the same prompt, then reveal at once.', 'Pick a prompt. Both draw for two minutes, then count down and hold your drawings up together.', array['Our first date', 'A cat on holiday', 'Your dream breakfast', 'Us at 80'], 10, 'medium', 'drawing', array['creative','playful'], 'Paper and pen'),
(19, 'Pass the Doodle', 'creative_chaos', 'One draws a squiggle, the other turns it into something.', 'Draw a random squiggle and show it. Your partner copies it and turns it into a picture. Swap.', '{}', 10, 'medium', 'drawing', array['creative','silly'], 'Paper and pen'),
(20, 'Couple Band', 'creative_chaos', 'Invent your band, your album — and hum the hit.', 'Decide your band name, genre, album title and first single. Then perform ten seconds of the hit.', '{}', 10, 'high', 'storytelling', array['silly','creative'], null),
(21, 'Design a Flag for Us', 'creative_chaos', 'Your two-person country needs a flag.', 'Each sketch a flag for your tiny country of two, then explain every colour and symbol.', '{}', 15, 'low', 'drawing', array['creative','romantic'], 'Paper and pen'),
(22, 'Commercial Break', 'creative_chaos', 'Make a 30-second ad for a random object.', 'Your partner picks an object in your room. You have 30 seconds to sell it like a TV ad. Swap.', '{}', 10, 'high', 'storytelling', array['silly'], null),
(23, 'Tiny Poem Duel', 'creative_chaos', 'Write a three-line poem about each other.', 'Set a three-minute timer. Each write a three-line poem about the other, then read them aloud.', array['Short, sweet, silly — all count'], 10, 'low', 'storytelling', array['romantic','creative'], 'Paper and pen'),
(24, 'Living Room Fashion Show', 'creative_chaos', 'Five minutes to put together a ridiculous outfit.', 'Set a five-minute timer to build an outfit from whatever''s around. Then do a catwalk on camera with commentary.', array['Airport chic', 'Rainforest gala', 'Retro holiday'], 15, 'high', 'storytelling', array['silly','playful'], 'Clothes and accessories'),
(25, 'Invent a Holiday', 'creative_chaos', 'Create a brand-new holiday just for you two.', 'Name it, give it a date, a food, a decoration and one strange tradition.', '{}', 10, 'low', 'storytelling', array['creative','romantic'], null),
(26, 'Monster Mash', 'creative_chaos', 'Each draw half a creature, then combine.', 'One draws a top half, the other a bottom half, without seeing each other''s. Hold them up together and name your creature.', '{}', 10, 'medium', 'drawing', array['silly','creative'], 'Paper and pen'),
(27, 'Movie Trailer Voice', 'creative_chaos', 'Narrate your day like an epic film trailer.', '"In a world…" — tell your partner about your day in your most dramatic trailer voice. Swap.', '{}', 5, 'high', 'storytelling', array['silly'], null),
(28, 'Fairy Tale Remix', 'creative_chaos', 'Retell a fairy tale starring the two of you.', 'Pick a fairy tale. Take turns telling it, but you two are the main characters and it''s set in your cities.', '{}', 15, 'medium', 'storytelling', array['creative','playful'], null),
(29, 'Logo Lab', 'creative_chaos', 'Design a logo for your relationship.', 'Five minutes to sketch a logo that represents you two. Present it like a branding agency.', '{}', 10, 'low', 'drawing', array['creative'], 'Paper and pen'),
(30, 'Shadow Puppet Theatre', 'creative_chaos', 'Act out a tiny story with hand shadows.', 'Dim the lights, shine a torch at a wall and perform a one-minute shadow story. Swap.', '{}', 10, 'high', 'storytelling', array['silly','playful'], 'A torch or lamp'),
-- Virtual Date Night
(31, 'Cook-Along', 'virtual_date_night', 'Cook the same simple dish together.', 'Choose something easy you both have ingredients for. Prop up your phones and cook step by step together, then eat together.', array['Pancakes', 'Fried rice', 'Eggs any style', 'Instant noodles, upgraded'], 30, 'medium', 'virtual_date', array['romantic','relaxed'], 'Ingredients you already have'),
(32, 'Snack Swap Tasting', 'virtual_date_night', 'Each taste a local snack and describe it.', 'Pick a snack that''s typical where you are. Describe it, eat it, rate it out of 10. Add it to your "try together" list.', '{}', 15, 'low', 'virtual_date', array['playful','relaxed'], 'A local snack'),
(33, 'Window Tour', 'virtual_date_night', 'Show your partner what''s outside right now.', 'Walk your partner around your home or street on camera. Point out three things you''d show them in person.', '{}', 15, 'medium', 'virtual_date', array['relaxed'], null),
(34, 'Watch Party', 'virtual_date_night', 'Watch the same short film or episode at the same time.', 'Pick something you can both stream. Count down "3, 2, 1, play" and watch together on the call.', array['Keep it short the first time'], 30, 'low', 'virtual_date', array['relaxed','romantic'], 'The same show or video'),
(35, 'Dress-Up Meal', 'virtual_date_night', 'Dress up and share a meal — even if one is breakfast.', 'Dress like it''s a fancy date. Eat whatever meal it is in your time zone and talk like you''re at a restaurant.', '{}', 30, 'low', 'virtual_date', array['romantic'], null),
(36, 'Virtual Museum Stroll', 'virtual_date_night', 'Browse a museum''s online collection together.', 'Pick a museum''s free online collection. Each find one piece you love and tell the other why.', '{}', 20, 'low', 'virtual_date', array['relaxed','deep'], 'A web browser'),
(37, 'Song Swap Listening Party', 'virtual_date_night', 'Take turns playing songs for each other.', 'Play one song each, three rounds. Before each, say why you chose it.', array['A song from your teens', 'One that''s "us"', 'One they''ve never heard'], 20, 'low', 'virtual_date', array['romantic','relaxed'], 'Music app'),
(38, 'Tea for Two', 'virtual_date_night', 'Make a warm drink and slow down together.', 'Each make a tea, coffee or hot chocolate. Sip slowly and tell each other one small memory it reminds you of.', '{}', 10, 'low', 'virtual_date', array['relaxed','romantic'], 'A warm drink'),
(39, 'Sky Swap', 'virtual_date_night', 'Show each other the sky right now.', 'Point your cameras at the sky — one of you may see stars while the other sees morning. Describe what you see.', '{}', 5, 'low', 'virtual_date', array['relaxed','romantic'], null),
(40, 'Read to Me', 'virtual_date_night', 'Read something short aloud to each other.', 'Pick a short story, poem or a few pages of a book. Read aloud, then swap.', '{}', 15, 'low', 'virtual_date', array['romantic','relaxed'], 'Something to read'),
(41, 'Plan a Pretend Date', 'virtual_date_night', 'Plan the perfect date in your partner''s city.', 'Describe, in detail, a date you''d plan for when you''re in their city: where, what to eat, what to wear.', '{}', 15, 'low', 'talking', array['romantic','playful'], null),
(42, 'Stretch Buddies', 'virtual_date_night', 'Do a gentle 10-minute stretch together.', 'Follow each other through 10 minutes of easy stretches. Take turns choosing the next one.', '{}', 10, 'high', 'virtual_date', array['playful','relaxed'], 'A bit of floor space'),
(43, 'Routine Company', 'virtual_date_night', 'Keep each other company during a daily routine.', 'One of you might be making breakfast while the other winds down for bed. Do it together on camera and chat.', '{}', 10, 'low', 'virtual_date', array['relaxed'], null),
(44, 'Grocery Run Together', 'virtual_date_night', 'Take your partner shopping with you.', 'Video-call from the shop. Your partner picks one surprise item for you to buy (within reason!).', '{}', 20, 'medium', 'virtual_date', array['playful'], 'A trip to the shop'),
(45, 'Candlelight Questions', 'virtual_date_night', 'Dim the lights and ask three slow questions.', 'Light a candle or dim the lights. Take turns asking three questions you''ve never asked each other.', array['What do you want more of this year?', 'What''s a smell that feels like home?'], 15, 'low', 'talking', array['romantic','deep'], 'A candle (optional)'),
-- Heart to Heart
(46, 'Rose, Bud, Thorn', 'heart_to_heart', 'A highlight, something you''re looking forward to, and a hard bit.', 'Each share your rose (best moment), bud (something you''re excited about) and thorn (something hard) from this week.', '{}', 10, 'low', 'talking', array['deep','relaxed'], null),
(47, 'Three Deep Questions', 'heart_to_heart', 'Pick three questions you''ve never asked each other.', 'Take turns choosing from the list. Answer slowly; follow-up questions welcome.', array['What would you change about how you were raised?', 'When did you last cry?', 'What does a perfect ordinary day look like?'], 20, 'low', 'talking', array['deep','romantic'], null),
(48, 'What Felt Like Love', 'heart_to_heart', 'Share which gestures from each other felt most loving lately.', 'Name one thing your partner did recently that made you feel loved, and one thing you''d love more of.', '{}', 10, 'low', 'talking', array['romantic','deep'], null),
(49, 'Gratitude Ping-Pong', 'heart_to_heart', 'Take turns finishing "I''m grateful for you because…"', 'Bounce "I''m grateful for you because…" back and forth. Keep going until you''re both smiling.', '{}', 10, 'low', 'talking', array['romantic'], null),
(50, 'Childhood Photo Story', 'heart_to_heart', 'Show a childhood photo and tell its story.', 'Hold a childhood photo up to the camera. Tell what was happening and who you were then.', '{}', 15, 'low', 'storytelling', array['deep','relaxed'], 'A childhood photo'),
(51, 'Letter to Your Younger Self', 'heart_to_heart', 'Tell your partner''s younger self something kind.', 'Pick an age your partner found hard. Tell their younger self what you''d want them to know.', '{}', 10, 'low', 'talking', array['deep','romantic'], null),
(52, 'What Home Feels Like', 'heart_to_heart', 'Describe what "home" means to you right now.', 'Each describe what home feels like now — a place, a person, a smell, a habit.', '{}', 10, 'low', 'talking', array['deep'], null),
(53, 'Distance Diaries', 'heart_to_heart', 'Your best and hardest moments of long distance.', 'Share your favourite moment and your hardest moment of being apart, and what helped.', '{}', 15, 'low', 'talking', array['deep'], null),
(54, 'Dreams Out Loud', 'heart_to_heart', 'Share a dream you''ve never fully said out loud.', 'Take turns sharing a dream — big or small — and the first tiny step towards it.', '{}', 15, 'low', 'talking', array['deep','romantic'], null),
(55, 'Small Wins Party', 'heart_to_heart', 'Celebrate each other''s small wins this week.', 'List three small wins each. Your partner cheers loudly for every one.', '{}', 5, 'medium', 'talking', array['playful','romantic'], null),
(56, 'Comfort Menu', 'heart_to_heart', 'Tell each other what helps when you''re low.', 'Each share what helps when you''re sad, stressed or tired — and what doesn''t. Write the other''s down.', '{}', 10, 'low', 'talking', array['deep'], 'Somewhere to note it'),
(57, 'Two Quiet Minutes', 'heart_to_heart', 'Look at each other quietly, then share what you felt.', 'Set a two-minute timer. Just look at each other, no talking. Then each say one word for how it felt.', '{}', 5, 'low', 'talking', array['romantic'], null),
(58, 'Appreciation Spotlight', 'heart_to_heart', 'Two minutes of nonstop praise, then swap.', 'Talk for two minutes about everything you appreciate about your partner. No interruptions. Swap.', '{}', 10, 'medium', 'talking', array['romantic','playful'], null),
(59, 'First Thing When I See You', 'heart_to_heart', 'What you''re most excited to do in person.', 'Each describe the first hour of your next visit in detail — and one small thing you can''t wait to do.', '{}', 10, 'low', 'talking', array['romantic'], null),
(60, 'Values Sort', 'heart_to_heart', 'Pick your top three values and compare.', 'From the list, each choose your top three values. Compare and talk about where they show up in your life.', array['Family', 'Adventure', 'Security', 'Creativity', 'Faith', 'Freedom', 'Kindness', 'Growth', 'Fun', 'Honesty'], 15, 'low', 'talking', array['deep'], null),
-- Silly & Random
(61, 'Accent Swap', 'silly_random', 'Say a sentence in each other''s accent.', 'Your partner gives you a sentence. Say it in your best impression of their accent. Swap.', '{}', 5, 'high', 'talking', array['silly'], null),
(62, 'Tongue Twister Exchange', 'silly_random', 'Teach a tongue twister in your language.', 'Teach each other a tongue twister in Malay, Iban, Spanish or English. Try it three times, faster each time.', '{}', 5, 'high', 'talking', array['silly','playful'], null),
(63, 'Would You Rather: Ridiculous Edition', 'silly_random', 'Absurd either-or questions.', 'Take turns asking ridiculous "would you rather" questions. You must explain your answer.', array['Would you rather have spaghetti hair or sweat maple syrup?'], 10, 'medium', 'talking', array['silly'], null),
(64, 'Funny Face Freeze', 'silly_random', 'Pull your best face — your partner takes the screenshot.', 'On "go", both pull the funniest face you can and hold it. Screenshot each other. Best of three.', '{}', 5, 'high', 'talking', array['silly'], null),
(65, 'Nature Documentary', 'silly_random', 'Narrate your partner like a wildlife documentary.', 'One of you does something ordinary (making tea, tidying). The other narrates in a hushed documentary voice.', '{}', 5, 'high', 'storytelling', array['silly'], null),
(66, 'Opposite Answers', 'silly_random', 'Answer everything with the opposite of the truth.', 'For five minutes, answer every question with the opposite of the truth. Your partner guesses the real answers.', '{}', 10, 'medium', 'guessing', array['silly','playful'], null),
(67, 'Exclusive Interview', 'silly_random', 'Interview your pet, plant or a stuffed toy.', 'Your partner interviews your pet, plant or toy. You answer in its voice.', '{}', 5, 'high', 'storytelling', array['silly'], 'A pet, plant or toy'),
(68, 'Random Word Rant', 'silly_random', 'Rant passionately about a random word for 60 seconds.', 'Your partner gives you a random word. Rant about it with total passion for 60 seconds. Swap.', array['Spoons', 'Tuesdays', 'Pigeons', 'Socks', 'Umbrellas'], 10, 'high', 'talking', array['silly'], null),
(69, 'Show & Tell: Weirdest Thing', 'silly_random', 'Show the strangest thing you own.', 'Find the weirdest object in your home and explain its full backstory.', '{}', 10, 'medium', 'talking', array['silly','playful'], null),
(70, 'Lip Sync Battle', 'silly_random', 'Perform a song with full commitment.', 'Each choose a song and lip-sync it dramatically. Props encouraged.', '{}', 10, 'high', 'talking', array['silly','playful'], 'Music app'),
(71, 'Rock-Paper-Scissors Championship', 'silly_random', 'Best of seven, with dramatic commentary.', 'Play best of seven. Between rounds, give sports-commentator analysis of each other''s strategy.', '{}', 5, 'high', 'talking', array['silly'], null),
(72, 'Bad Pickup Line Contest', 'silly_random', 'Your cheesiest lines, delivered with a straight face.', 'Take turns delivering the worst pickup lines you can think of. First to laugh loses the round.', '{}', 5, 'medium', 'talking', array['silly','romantic'], null),
(73, 'The Conspiracy of Us', 'silly_random', 'Invent a silly conspiracy about how you met.', 'Together, invent a wildly unlikely theory that "explains" how you really met. The more evidence, the better.', '{}', 10, 'medium', 'storytelling', array['silly','creative'], null),
(74, 'Slow-Motion Replay', 'silly_random', 'Re-enact an embarrassing moment in slow motion.', 'Act out a small embarrassing moment from your week, in slow motion, with sound effects.', '{}', 5, 'high', 'storytelling', array['silly'], null),
(75, 'Alphabet Story', 'silly_random', 'A story where each sentence starts with the next letter.', 'Take turns: first sentence starts with A, the next with B, and so on. See how far you get.', '{}', 10, 'medium', 'storytelling', array['silly','creative'], null),
-- Future Adventures
(76, 'Bucket List Draft', 'future_adventures', 'List ten things to do together, then pick your top three.', 'Brainstorm ten things to do together someday. Agree on your top three.', '{}', 15, 'low', 'talking', array['romantic'], 'Somewhere to note it'),
(77, 'Dream Trip Planner', 'future_adventures', 'Plan a three-day trip together.', 'Pick a destination. Take turns planning mornings and afternoons for three days.', '{}', 20, 'medium', 'talking', array['playful','romantic'], null),
(78, 'Future Home Tour', 'future_adventures', 'Walk through your imagined future home room by room.', 'Take turns describing each room of a home you might share one day — one detail each.', '{}', 15, 'low', 'storytelling', array['romantic'], null),
(79, 'A Tuesday in Five Years', 'future_adventures', 'Describe an ordinary day, five years from now.', 'Take turns narrating a completely ordinary Tuesday together, five years from now.', '{}', 10, 'low', 'storytelling', array['deep','romantic'], null),
(80, 'Name Our Future Pet', 'future_adventures', 'Debate names for an imaginary pet.', 'Decide what kind of pet you''d have, then pitch names until you agree.', '{}', 5, 'medium', 'talking', array['silly','playful'], null),
(81, 'Next Visit Wishlist', 'future_adventures', 'Plan five must-dos for your next visit.', 'Each suggest must-dos for your next time together. Agree on five.', '{}', 10, 'low', 'talking', array['romantic'], null),
(82, 'Imaginary Budget Weekend', 'future_adventures', 'Plan a weekend with an imaginary budget.', 'You have a pretend budget for a weekend together. Plan how to spend every bit of it.', '{}', 15, 'medium', 'talking', array['playful'], null),
(83, 'Tradition Builder', 'future_adventures', 'Invent rituals for birthdays and anniversaries.', 'Design a little tradition for each other''s birthdays and for your anniversary.', '{}', 10, 'low', 'talking', array['romantic'], null),
(84, 'One Year From Now', 'future_adventures', 'Write a note to yourselves to open in a year.', 'Each write a short note for the two of you to read in a year. Save it somewhere safe.', '{}', 10, 'low', 'talking', array['deep','romantic'], 'Somewhere to write'),
(85, 'Learn Something Together', 'future_adventures', 'Choose a skill to learn together and plan the first lesson.', 'Pick something you''d both like to learn. Plan a first tiny step you can each do this week.', '{}', 10, 'low', 'talking', array['playful'], null),
(86, 'Map Our Future', 'future_adventures', 'Sketch a map of places you want to live or visit.', 'Each draw a rough map with the places you''d love to visit or live. Compare and connect them.', '{}', 15, 'low', 'drawing', array['creative','romantic'], 'Paper and pen'),
(87, 'Us at Eighty', 'future_adventures', 'Describe your 80-year-old selves'' perfect day.', 'Take turns describing what your 80-year-old selves do on a perfect day.', '{}', 10, 'low', 'storytelling', array['romantic','silly'], null),
(88, 'Celebration Planner', 'future_adventures', 'Design your dream celebration for a future milestone.', 'Pick a future milestone you''d like to celebrate and plan the party: place, food, music, guests.', '{}', 15, 'low', 'talking', array['romantic'], null),
(89, 'City Swap', 'future_adventures', 'Imagine living in each other''s city for a week.', 'Describe what you''d do each day living in your partner''s city, and ask them to correct you.', '{}', 10, 'low', 'talking', array['playful'], null),
(90, 'Three Words for Next Year', 'future_adventures', 'Pick three words for the year ahead together.', 'Each choose three words for what you hope next year feels like. Find the overlap.', '{}', 10, 'low', 'talking', array['deep'], null);
